import{_ as e,c as o,o as n,a3 as a}from"./chunks/framework.Dokpd4od.js";const h=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/configuration/index.md","filePath":"master/finance/configuration/index.md","lastUpdated":1793074831000}'),s={name:"master/finance/configuration/index.md"};function i(r,t,c,d,u,g){return n(),o("div",null,t[0]||(t[0]=[a('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Configuration holds the one-time setup of finance. <strong>Settings</strong> switch features on and set defaults. <strong>Configurations</strong> are the lists that invoices, bills and payments use, such as taxes and payment terms.</p><blockquote><p><strong>In simple words:</strong> Settings switch features on. Configurations fill them with data.</p></blockquote><h2 id="settings-pages" tabindex="-1">Settings pages <a class="header-anchor" href="#settings-pages" aria-label="Permalink to &quot;Settings pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>App</th><th>Menu path</th><th>What it controls</th></tr></thead><tbody><tr><td>Manage Products</td><td>Invoices</td><td><code>Invoices → Settings → Manage Products</code></td><td><strong>Unit of Measure</strong></td></tr><tr><td>Manage Products</td><td>Accounting</td><td><code>Accounting → Settings → Manage Products</code></td><td><strong>Variants</strong> and <strong>Unit of Measure</strong></td></tr><tr><td>Manage Taxes</td><td>Accounting</td><td><code>Accounting → Settings → Manage Taxes</code></td><td>Default taxes, rounding and price display. See <a href="./../taxes/tax-settings.html">Tax settings</a></td></tr><tr><td>Manage Customer Invoice</td><td>Accounting</td><td><code>Accounting → Settings → Manage Customer Invoice</code></td><td><strong>Cash Rounding</strong> and <strong>Default Incoterm</strong></td></tr><tr><td>Manage Default Accounts</td><td>Accounting</td><td><code>Accounting → Settings → Manage Default Accounts</code></td><td>Exchange difference, bank transfer and product accounts. See <a href="./../get-started/default-accounts.html">Default accounts</a></td></tr></tbody></table><p>Click <strong>Save changes</strong> after you change a setting.</p><h3 id="manage-products" tabindex="-1">Manage Products <a class="header-anchor" href="#manage-products" aria-label="Permalink to &quot;Manage Products&quot;">​</a></h3><ul><li><strong><em>Variants:</em></strong> Set product attributes such as colour or size to manage variants. Accounting app only.</li><li><strong><em>Unit of Measure:</em></strong> Sell and purchase products in different units of measure.</li></ul><h3 id="manage-customer-invoice" tabindex="-1">Manage Customer Invoice <a class="header-anchor" href="#manage-customer-invoice" aria-label="Permalink to &quot;Manage Customer Invoice&quot;">​</a></h3><ul><li><strong><em>Default Incoterm:</em></strong> Choose the incoterm that new invoices use by default. See <a href="./../customer-invoices/incoterms.html">Incoterms</a>.</li><li><strong><em>Cash Rounding:</em></strong> A toggle for the lowest currency denomination accepted for cash payments.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Until the company is set up, the Accounting settings pages show a <strong>Set up accounting</strong> message. See <a href="./../get-started/accounting-setup.html">Accounting setup</a>.</p></div><h2 id="configuration-pages" tabindex="-1">Configuration pages <a class="header-anchor" href="#configuration-pages" aria-label="Permalink to &quot;Configuration pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Invoices app</th><th>Accounting app</th><th>Guide</th></tr></thead><tbody><tr><td>Payment Terms</td><td><code>Invoices → Configurations → Invoicing → Payment Terms</code></td><td><code>Accounting → Configurations → Invoicing → Payment Terms</code></td><td><a href="./../customer-invoices/payment-terms.html">Payment terms</a></td></tr><tr><td>Incoterms</td><td><code>Invoices → Configurations → Invoicing → Incoterms</code></td><td><code>Accounting → Configurations → Invoicing → Incoterms</code></td><td><a href="./../customer-invoices/incoterms.html">Incoterms</a></td></tr><tr><td>Bank Accounts</td><td><code>Invoices → Configurations → Bank Accounts</code></td><td>-</td><td><a href="./../payments/bank-accounts.html">Bank accounts</a></td></tr><tr><td>Currencies</td><td><code>Invoices → Configurations → Accounting → Currencies</code></td><td><code>Accounting → Configurations → Accounting → Currencies</code></td><td><a href="./../get-started/multi-currency.html">Multi-currency</a></td></tr><tr><td>Chart of Accounts</td><td>-</td><td><code>Accounting → Configurations → Accounting → Chart of Accounts</code></td><td><a href="./../get-started/chart-of-accounts.html">Chart of accounts</a></td></tr><tr><td>Journals</td><td>-</td><td><code>Accounting → Configurations → Accounting → Journals</code></td><td><a href="./../get-started/journals.html">Journals</a></td></tr><tr><td>Fiscal Positions</td><td>-</td><td><code>Accounting → Configurations → Accounting → Fiscal Positions</code></td><td><a href="./../taxes/fiscal-positions.html">Fiscal positions</a></td></tr><tr><td>Tax Groups</td><td><code>Invoices → Configurations → Accounting → Tax Groups</code></td><td><code>Accounting → Configurations → Accounting → Tax Groups</code></td><td><a href="./../taxes/tax-groups.html">Tax groups</a></td></tr><tr><td>Taxes</td><td><code>Invoices → Configurations → Accounting → Taxes</code></td><td><code>Accounting → Configurations → Accounting → Taxes</code></td><td><a href="./../taxes/taxes.html">Taxes</a></td></tr><tr><td>Attributes</td><td><code>Invoices → Configurations → Products → Attributes</code></td><td><code>Accounting → Configurations → Products → Attributes</code></td><td><a href="./../../sales/sales/configuration/product-attributes.html">Product attributes</a></td></tr><tr><td>Categories</td><td><code>Invoices → Configurations → Products → Categories</code></td><td><code>Accounting → Configurations → Products → Categories</code></td><td><a href="./../../sales/sales/configuration/product-categories.html">Product categories</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Work through the pages in the order given in <a href="./../#set-up-in-this-order">Finance</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Finance overview</a></li><li><a href="./../get-started/">Get started</a></li><li><a href="./../taxes/">Taxes</a></li></ul>',16)]))}const f=e(s,[["render",i]]);export{h as __pageData,f as default};
